{"script": "res = env.run(["cargo", "test", "--workspace"], check = False)
out = res.stdout + "\n" + res.stderr
lines = out.lines()
# Find every "test result:" line and every "---- ... stdout ----" block
results = []
for i, l in enumerate(lines):
    if l.startswith("test result:") or l.startswith("     Running") or l.startswith("   Doc-tests") or l.startswith("error") or l.startswith("warning: unused"):
        results.append(l)
blocks = str(text(out).grep("^---- ", after = 8))
return {
  "code": res.code,
  "markers": results,
  "failure_blocks": blocks,
}"}

